head.script:
/*
 * WAEA-917 가이드 샘플 - jquerySupport defaultLoad 설정으로 엔진 기본 jQuery 자동 로딩 제어
 *
 * [설정 규격] config.xml (또는 config.js)
 *   <jquerySupport defaultLoad="false" />
 *     - src 미지정 + defaultLoad="false" : 엔진 기본 jQuery(externalJS/jquery/jquery-3.7.1.min.js) 미로드
 *     - defaultLoad 미지정(기본)         : 기존과 동일하게 엔진 기본 jQuery 로드 (하위호환)
 *     - src 지정 시                      : defaultLoad 값과 무관하게 지정한 jQuery 로드 (src 우선)
 *
 * [확인 방법]
 *   1. 기본 config 상태로 이 페이지를 열고 [상태 확인] : jQuery 3.7.1 로드됨
 *   2. config.xml에 <jquerySupport defaultLoad="false" /> 설정 후 새로고침 : jQuery 미로드
 *   3. src까지 지정하면 defaultLoad="false"여도 지정 jQuery가 로드됨
 */
scwin.onpageload = function() {
    scwin.checkStatus();
};

scwin.checkStatus = function() {
    var lines = [];
    var conf = "";
    try {
        conf = WebSquare.core.getConfiguration("/WebSquare/jquerySupport/@defaultLoad");
    } catch (e) {
        conf = "(조회 실패: " + e.message + ")";
    }
    var src = "";
    try {
        src = WebSquare.core.getConfiguration("/WebSquare/jquerySupport/@src");
    } catch (e) {
        src = "";
    }
    lines.push("config jquerySupport/@defaultLoad : " + (conf === "" ? "(미지정)" : conf));
    lines.push("config jquerySupport/@src         : " + (src === "" ? "(미지정)" : src));
    lines.push("window.jQuery 존재 여부            : " + (window.jQuery ? "true" : "false"));
    lines.push("jQuery 버전                        : " + (window.jQuery ? window.jQuery.fn.jquery : "-"));

    var scripts = document.querySelectorAll("script[src*='jquery']");
    var srcList = [];
    for (var i = 0; i < scripts.length; i++) {
        srcList.push(scripts[i].getAttribute("src"));
    }
    lines.push("문서 내 jQuery script 태그          : " + (srcList.length ? srcList.join(", ") : "(없음)"));

    textarea1.setValue(lines.join("\n"));
};
